package edu.bis701.exp01;
import org.apache.hadoop.conf.Configuration;import org.apache.hadoop.fs.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class HDFSOperations { public static void main(String[] a)throws Exception { Configuration c=new Configuration(); FileSystem fs=FileSystem.get(c); Path dir=new Path(a.length>0?a[0]:"/bis701/training");Path file=new Path(dir,"demo.txt");String s="Hello World!\nBig Data Lab\n";System.out.println("Input file:\n"+s);fs.mkdirs(dir);try(FSDataOutputStream o=fs.create(file,true)){o.write(s.getBytes(StandardCharsets.UTF_8));}System.out.println("HDFS listing:");for(FileStatus st:fs.listStatus(dir))System.out.println(st.getPath()+"\t"+st.getLen()+" bytes");System.out.println("HDFS file content:");try(BufferedReader r=new BufferedReader(new InputStreamReader(fs.open(file),StandardCharsets.UTF_8))){r.lines().forEach(System.out::println);}Path local=new Path("retrieved-demo.txt");fs.copyToLocalFile(false,file,local,true);System.out.println("Downloaded to "+local.toUri().getPath());System.out.print("Delete demo directory? [y/N]: ");if("y".equalsIgnoreCase(new BufferedReader(new InputStreamReader(System.in)).readLine())){fs.delete(dir,true);System.out.println("Deleted "+dir);}fs.close();}}
